#!/bin/bash
# Joins src/*.sh and the container-side files in src/payload/ into one script: dist/vpn-lxc.sh.
# The result is what you copy to the Proxmox host. Edit src/, never dist/.
set -euo pipefail
cd "$(dirname "$0")"
out=${1:-dist/vpn-lxc.sh}
EOFTAG=VPNLXC_PAYLOAD_EOF

emit_payload() {
    local f
    cat <<'BANNER'
# ════════════════════════════════════════════════════════════
#  Container-side files. Written to the stage on the host and
#  pushed into containers with pct. Nothing here runs on the host.
#  (generated by build.sh from src/payload/)
# ════════════════════════════════════════════════════════════

write_payload() {   # write_payload <dir>
local d=$1
mkdir -p "$d"
BANNER
    while IFS= read -r f; do
        [ -n "$f" ] || continue
        [ -f "src/payload/$f" ] || { echo "build: missing src/payload/$f" >&2; exit 1; }
        if grep -qx "$EOFTAG" "src/payload/$f"; then echo "build: $f contains the heredoc terminator" >&2; exit 1; fi
        printf '\ncat > "$d/%s" <<'"'"'%s'"'"'\n' "$f" "$EOFTAG"
        cat "src/payload/$f"
        printf '%s\n' "$EOFTAG"
    done < src/payload/MANIFEST
    echo '}'
}

mkdir -p "$(dirname "$out")"
{
    cat src/[0-3]*.sh
    emit_payload
    cat src/[5-9]*.sh
} > "$out"
bash -n "$out"
chmod 755 "$out"

( cd "$(dirname "$out")" && sha256sum "$(basename "$out")" > "$(basename "$out").sha256" )
echo "built $out ($(wc -l < "$out") lines)"
